#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import datetime as _dt
import importlib.util
import py_compile
import shutil
import subprocess
import sys
from pathlib import Path


VERSION = "0.4.0"

FE_B64 = {'src/api/labServiceApi.ts': '', 'src/Pages/LabView.tsx': '', 'src/Pages/ImageProcessingLabPage.tsx': '', 'src/components/VisionLabs/ImageProcessing/types.ts': '', 'src/components/VisionLabs/ImageProcessing/ProcessingStack.tsx': '', 'src/components/VisionLabs/ImageProcessing/useImageLabController.ts': ''}
BE_B64 = {'app/services/vision_labs/service/__init__.py': '', 'app/services/vision_labs/service/models.py': '', 'app/services/vision_labs/service/repository.py': '', 'app/services/vision_labs/service/runtime.py': '', 'app/api/v1/endpoints/lab_service_api.py': '', 'tests/vision_labs/test_lab_service_core.py': ''}

FE_FILES = {
    rel: base64.b64decode(payload).decode("utf-8")
    for rel, payload in FE_B64.items()
}
BE_FILES = {
    rel: base64.b64decode(payload).decode("utf-8")
    for rel, payload in BE_B64.items()
}

ROUTER_IMPORT = "from app.api.v1.endpoints import lab_service_api"
ROUTER_MOUNT = (
    'api_router.include_router('
    'lab_service_api.router, prefix="/lab-services", tags=["Lab Services"])'
)


def resolve_roots(frontend_arg, backend_arg):
    cwd = Path.cwd().resolve()
    fe_candidates = []
    be_candidates = []

    if frontend_arg:
        fe_candidates.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg:
        be_candidates.append(Path(backend_arg).expanduser().resolve())

    fe_candidates += [
        cwd,
        cwd / "LambdaVisionSuper",
        cwd.parent / "LambdaVisionSuper",
    ]
    be_candidates += [
        cwd,
        cwd / "LambdaVisionSuperBackEnd",
        cwd.parent / "LambdaVisionSuperBackEnd",
    ]

    frontend = next(
        (
            p for p in fe_candidates
            if (
                p
                / "src/components/VisionLabs/ImageProcessing/useImageLabController.ts"
            ).exists()
            and (p / "src/Pages/LabView.tsx").exists()
        ),
        None,
    )
    backend = next(
        (
            p for p in be_candidates
            if (
                p
                / "app/services/vision_labs/image/runtime.py"
            ).exists()
            and (p / "app/api/v1/api.py").exists()
        ),
        None,
    )

    if frontend is None:
        raise RuntimeError(
            "Cannot locate Lambda Vision frontend. "
            "Use --frontend /path/to/LambdaVisionSuper"
        )
    if backend is None:
        raise RuntimeError(
            "Cannot locate Lambda Vision backend. "
            "Use --backend /path/to/LambdaVisionSuperBackEnd"
        )

    return frontend, backend


def patch_router(text):
    changed = False

    if ROUTER_IMPORT not in text:
        lines = text.splitlines()
        inserted = False

        for index, line in enumerate(lines):
            if line.startswith("from app.api.v1.endpoints import "):
                lines.insert(index + 1, ROUTER_IMPORT)
                inserted = True
                break

        if not inserted:
            for index, line in enumerate(lines):
                if line.strip() == "from fastapi import APIRouter":
                    lines.insert(index + 1, ROUTER_IMPORT)
                    inserted = True
                    break

        if not inserted:
            raise RuntimeError(
                "Could not find a safe import anchor in app/api/v1/api.py"
            )

        text = "\n".join(lines) + ("\n" if text.endswith("\n") else "")
        changed = True

    if ROUTER_MOUNT not in text:
        lines = text.splitlines()
        insert_after = None
        for index, line in enumerate(lines):
            if "api_router.include_router(" in line:
                insert_after = index

        if insert_after is None:
            raise RuntimeError(
                "Could not find api_router.include_router(...) anchor "
                "in app/api/v1/api.py"
            )

        lines.insert(insert_after + 1, ROUTER_MOUNT)
        text = "\n".join(lines) + ("\n" if text.endswith("\n") else "")
        changed = True

    return text, changed


def preflight_frontend(frontend):
    checks = {
        "src/components/VisionLabs/ImageProcessing/useImageLabController.ts": [
            "const initialViewerPanes",
            "const runNow = useCallback",
            "viewerSourcesForStack",
        ],
        "src/components/VisionLabs/ImageProcessing/ProcessingStack.tsx": [
            "GripVertical",
            "onParameterChange",
        ],
        "src/Pages/ImageProcessingLabPage.tsx": [
            "IMAGE PROCESSING LAB",
            "ImageWorkbench",
        ],
        "src/Pages/LabView.tsx": [
            "VISION LABS",
            "Image Processing LAB",
        ],
        "src/components/VisionLabs/ImageProcessing/types.ts": [
            "export interface ViewerPane",
            "export interface ImagePipelineDefinition",
        ],
    }

    for rel, signatures in checks.items():
        path = frontend / rel
        if not path.exists():
            raise RuntimeError(f"Required frontend file is missing: {rel}")
        text = path.read_text(encoding="utf-8")

        if rel in FE_FILES and text == FE_FILES[rel]:
            continue

        missing = [signature for signature in signatures if signature not in text]
        if missing:
            raise RuntimeError(
                f"{rel} is too different from the expected Image LAB v0.2.x "
                f"baseline; missing signatures: {missing}"
            )


def backup(frontend, backend, paths):
    stamp = _dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    root = (
        frontend
        / ".lambda_updater_backups"
        / f"lab_service_foundation_v0040_{stamp}"
    )
    root.mkdir(parents=True, exist_ok=True)

    for path in paths:
        if not path.exists():
            continue

        try:
            rel = path.relative_to(frontend)
            prefix = Path("frontend")
        except ValueError:
            rel = path.relative_to(backend)
            prefix = Path("backend")

        dest = root / prefix / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, dest)

    return root


def file_status(path, desired):
    if not path.exists():
        return "CREATE"
    return "OK" if path.read_text(encoding="utf-8") == desired else "UPDATE"


def scan(frontend, backend):
    print("=" * 86)
    print("LAMBDA VISION LAB SERVICE FOUNDATION V0.4.0")
    print("=" * 86)
    print(f"Frontend : {frontend}")
    print(f"Backend  : {backend}")
    print()

    preflight_frontend(frontend)

    for rel, desired in FE_FILES.items():
        print(
            f"  [{file_status(frontend / rel, desired):6}] "
            f"FE  {rel}"
        )

    for rel, desired in BE_FILES.items():
        print(
            f"  [{file_status(backend / rel, desired):6}] "
            f"BE  {rel}"
        )

    router_text = (
        backend / "app/api/v1/api.py"
    ).read_text(encoding="utf-8")
    router_ok = ROUTER_IMPORT in router_text and ROUTER_MOUNT in router_text
    print(
        f"  [{'OK' if router_ok else 'PATCH':6}] "
        "BE  app/api/v1/api.py -> /lab-services"
    )

    print()
    print("Features:")
    print("  - Image LAB Execution Mode: Live / Manual")
    print("  - Manual mode keeps parameter/stack changes local until Run")
    print("  - Lab Service draft mode with arbitrary stack checkpoints")
    print("  - Named, typed service output contract")
    print("  - Immutable versioned pipeline snapshots")
    print("  - Generic LabServiceRuntime.run(service, inputs) contract")
    print("  - Image-processing runtime adapter today; future LAB adapters can plug in")
    print("  - Runtime prunes nodes after the last required checkpoint")
    print("  - /labs shows deployed Lab Services and a manual runner")
    print("  - Manual runner uses the same runtime path future modules will call")
    return 0


def apply(frontend, backend):
    preflight_frontend(frontend)

    router_path = backend / "app/api/v1/api.py"
    touched = (
        [frontend / rel for rel in FE_FILES]
        + [backend / rel for rel in BE_FILES]
        + [router_path]
    )
    backup_root = backup(frontend, backend, touched)

    for rel, desired in FE_FILES.items():
        path = frontend / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists() or path.read_text(encoding="utf-8") != desired:
            path.write_text(desired, encoding="utf-8")
            print(f"[WRITE] FE {rel}")

    for rel, desired in BE_FILES.items():
        path = backend / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists() or path.read_text(encoding="utf-8") != desired:
            path.write_text(desired, encoding="utf-8")
            print(f"[WRITE] BE {rel}")

    router_old = router_path.read_text(encoding="utf-8")
    router_new, changed = patch_router(router_old)
    if changed:
        router_path.write_text(router_new, encoding="utf-8")
        print("[PATCH] BE app/api/v1/api.py -> /lab-services")

    print(f"[OK] Backup: {backup_root}")
    print("Run verify next.")
    return 0


def _backend_smoke(backend):
    code = r'''
import tempfile
from pathlib import Path

import numpy as np

from app.services.vision_labs.image.operators import load_builtin_operators
from app.services.vision_labs.image.pipeline import ImagePipelineDefinition, model_to_dict
from app.services.vision_labs.image.types import ColorSpace, ImageFrame
from app.services.vision_labs.service.models import (
    LabServiceOutputBinding,
    LabServicePort,
)
from app.services.vision_labs.service.repository import LabServiceRepository
from app.services.vision_labs.service.runtime import LabServiceRuntime

load_builtin_operators()

pipeline = ImagePipelineDefinition(
    nodes=[
        {
            "id": "gray",
            "operator_id": "image.color.grayscale",
            "parameters": {},
            "enabled": True,
        },
        {
            "id": "blur",
            "operator_id": "image.filter.gaussian",
            "parameters": {"kernel_size": 5, "sigma": 0.0},
            "enabled": True,
        },
        {
            "id": "threshold",
            "operator_id": "image.threshold.binary",
            "parameters": {"threshold": 100, "invert": False},
            "enabled": True,
        },
    ],
    connections=[
        {
            "source": {"node_id": "gray", "port": "image"},
            "target": {"node_id": "blur", "port": "image"},
        },
        {
            "source": {"node_id": "blur", "port": "image"},
            "target": {"node_id": "threshold", "port": "image"},
        },
    ],
    inputs={"image": {"node_id": "gray", "port": "image"}},
    outputs={"result": {"node_id": "threshold", "port": "mask"}},
)

with tempfile.TemporaryDirectory() as temp:
    repo = LabServiceRepository(Path(temp) / "services")
    first = repo.deploy(
        name="Image Prep",
        lab_type="image_processing",
        inputs={"image": LabServicePort(type="image")},
        outputs={
            "gray": LabServiceOutputBinding(
                type="image",
                node_id="gray",
                port="image",
            ),
            "blurred": LabServiceOutputBinding(
                type="image",
                node_id="blur",
                port="image",
            ),
        },
        pipeline_snapshot=model_to_dict(pipeline),
    )
    second = repo.deploy(
        name="Image Prep",
        service_id=first.service_id,
        lab_type="image_processing",
        inputs=first.inputs,
        outputs=first.outputs,
        pipeline_snapshot=model_to_dict(pipeline),
    )

    assert first.version == 1
    assert second.version == 2
    assert repo.get(first.service_id).version == 2

    image = np.zeros((64, 96, 3), dtype=np.uint8)
    image[20:40, 20:70] = 255
    run = LabServiceRuntime().run(
        second,
        {
            "image": ImageFrame(
                image,
                color_space=ColorSpace.BGR,
            )
        },
    )

    assert set(run.outputs) == {"gray", "blurred"}
    assert run.outputs["gray"].shape == (64, 96)
    assert run.outputs["blurred"].shape == (64, 96)

print("LAB_SERVICE_SMOKE_OK")
print("service_version=", second.version)
print("outputs=", sorted(run.outputs))
'''
    return subprocess.run(
        [sys.executable, "-c", code],
        cwd=str(backend),
        text=True,
        capture_output=True,
    )


def _typescript_syntax_check(frontend):
    node_code = r'''
const fs = require("fs");
const ts = require("typescript");

const files = process.argv.slice(1);
let failed = false;

for (const file of files) {
  const source = fs.readFileSync(file, "utf8");
  const result = ts.transpileModule(source, {
    fileName: file,
    reportDiagnostics: true,
    compilerOptions: {
      jsx: ts.JsxEmit.ReactJSX,
      target: ts.ScriptTarget.ES2020,
      module: ts.ModuleKind.ESNext,
    },
  });

  const errors = (result.diagnostics || []).filter(
    (item) => item.category === ts.DiagnosticCategory.Error,
  );

  if (errors.length > 0) {
    failed = true;
    console.error("TYPE_SCRIPT_ERROR", file);
    for (const item of errors) {
      console.error(ts.flattenDiagnosticMessageText(item.messageText, "\n"));
    }
  }
}

process.exit(failed ? 1 : 0);
'''
    files = [
        str(frontend / rel)
        for rel in FE_FILES
        if rel.endswith((".ts", ".tsx"))
    ]
    return subprocess.run(
        ["node", "-e", node_code, *files],
        cwd=str(frontend),
        text=True,
        capture_output=True,
    )


def verify(frontend, backend, skip_build=False):
    print("=" * 86)
    print("VERIFY LAMBDA VISION LAB SERVICE FOUNDATION V0.4.0")
    print("=" * 86)

    failures = 0

    static_checks = [
        (
            "Manual execution mode suppresses immediate execution",
            "executionModeRef.current === 'manual'"
            in (
                frontend
                / "src/components/VisionLabs/ImageProcessing/useImageLabController.ts"
            ).read_text(encoding="utf-8"),
        ),
        (
            "Image LAB exposes deployable service checkpoints",
            "toggleServiceOutput"
            in (
                frontend
                / "src/components/VisionLabs/ImageProcessing/useImageLabController.ts"
            ).read_text(encoding="utf-8")
            and "LAB SERVICE OUTPUT"
            in (
                frontend
                / "src/components/VisionLabs/ImageProcessing/ProcessingStack.tsx"
            ).read_text(encoding="utf-8"),
        ),
        (
            "/labs contains deployed-service manual runner",
            "Manual Runner"
            in (frontend / "src/Pages/LabView.tsx").read_text(encoding="utf-8")
            and "LabServiceAPI.runImage"
            in (frontend / "src/Pages/LabView.tsx").read_text(encoding="utf-8"),
        ),
        (
            "Generic service runtime exists",
            "class LabServiceRuntime"
            in (
                backend
                / "app/services/vision_labs/service/runtime.py"
            ).read_text(encoding="utf-8"),
        ),
        (
            "Service runtime prunes unused descendants",
            "def _prune_image_pipeline"
            in (
                backend
                / "app/services/vision_labs/service/runtime.py"
            ).read_text(encoding="utf-8"),
        ),
        (
            "Versioned repository exists",
            "def _next_version"
            in (
                backend
                / "app/services/vision_labs/service/repository.py"
            ).read_text(encoding="utf-8"),
        ),
    ]

    for label, ok in static_checks:
        print(f"[{'OK' if ok else 'FAIL'}] {label}")
        failures += 0 if ok else 1

    router_text = (
        backend / "app/api/v1/api.py"
    ).read_text(encoding="utf-8")
    router_ok = ROUTER_IMPORT in router_text and ROUTER_MOUNT in router_text
    print(f"[{'OK' if router_ok else 'FAIL'}] /api/v1/lab-services router mounted")
    failures += 0 if router_ok else 1

    for rel in BE_FILES:
        path = backend / rel
        if not rel.endswith(".py"):
            continue
        try:
            py_compile.compile(str(path), doraise=True)
            print(f"[OK] Python syntax {rel}")
        except Exception as exc:
            print(f"[FAIL] Python syntax {rel}: {exc}")
            failures += 1

    smoke = _backend_smoke(backend)
    if smoke.returncode == 0:
        print("[OK] Lab Service runtime/repository smoke")
        if smoke.stdout.strip():
            print(smoke.stdout.strip())
    else:
        print("[FAIL] Lab Service runtime/repository smoke")
        print((smoke.stdout + "\n" + smoke.stderr).strip())
        failures += 1

    ts_check = _typescript_syntax_check(frontend)
    if ts_check.returncode == 0:
        print("[OK] TypeScript syntax/transpile check")
    else:
        combined = (ts_check.stdout + "\n" + ts_check.stderr).strip()
        if "Cannot find module 'typescript'" in combined:
            print("[SKIP] TypeScript transpile check: typescript module not available to node")
        else:
            print("[FAIL] TypeScript syntax/transpile check")
            print(combined)
            failures += 1

    test_path = backend / "tests/vision_labs/test_lab_service_core.py"
    if importlib.util.find_spec("pytest") is None:
        print("[SKIP] pytest not installed; backend smoke already passed")
    else:
        proc = subprocess.run(
            [
                sys.executable,
                "-m",
                "pytest",
                "-q",
                str(test_path.relative_to(backend)),
            ],
            cwd=str(backend),
            text=True,
            capture_output=True,
        )
        if proc.returncode == 0:
            print("[OK] Lab Service regression test")
            if proc.stdout.strip():
                print(proc.stdout.strip())
        else:
            print("[FAIL] Lab Service regression test")
            print((proc.stdout + "\n" + proc.stderr).strip())
            failures += 1

    if (
        not skip_build
        and (frontend / "package.json").exists()
        and (frontend / "node_modules").exists()
    ):
        proc = subprocess.run(
            ["npm", "run", "build"],
            cwd=str(frontend),
        )
        if proc.returncode == 0:
            print("[OK] Frontend npm build")
        else:
            print("[FAIL] Frontend npm build")
            failures += 1
    else:
        print("[SKIP] Frontend npm build")

    if failures:
        print(f"[FAIL] Verification completed with {failures} issue(s).")
        return 1

    print("[OK] Lambda Vision Lab Service Foundation v0.4.0 verified.")
    return 0


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=["scan", "apply", "verify"])
    parser.add_argument("--frontend")
    parser.add_argument("--backend")
    parser.add_argument("--skip-build", action="store_true")
    args = parser.parse_args()

    try:
        frontend, backend = resolve_roots(args.frontend, args.backend)

        if args.command == "scan":
            return scan(frontend, backend)
        if args.command == "apply":
            return apply(frontend, backend)
        return verify(frontend, backend, skip_build=args.skip_build)
    except Exception as exc:
        print(f"[ERROR] {exc}")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
